      --focus-ring: #bfdbfe;
      --error-color: #dc2626;
      --radius: 0.5rem;
    }

    * {
      box-sizing: border-box;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background-color: var(--bg-page);
      color: var(--text-main);
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
      margin: 0;
      padding: 1rem;
    }

    .card {
      background-color: var(--bg-card);
      padding: 2rem;
      border-radius: var(--radius);
      box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
      width: 100%;
      max-width: 400px;
    }

    h1 {
      font-size: 1.5rem;
      font-weight: 700;
      margin-top: 0;
      margin-bottom: 0.5rem;
    }

    p.intro {
      color: var(--text-muted);
      margin-bottom: 1.5rem;
      font-size: 0.95rem;
    }

    .form-field {
      margin-bottom: 1.5rem;
    }

    .checkbox-container {
      display: flex;
      gap: 0.75rem;
      align-items: flex-start;
    }

    input[type="checkbox"] {
      width: 1.25rem;
      height: 1.25rem;
      margin-top: 0.125rem;
      cursor: pointer;
      accent-color: var(--primary-color);
      border: 1px solid var(--border-color);
      border-radius: 0.25rem;
    }

    input[type="checkbox"]:focus-visible {
      outline: 2px solid var(--primary-color);
      outline-offset: 2px;
    }

    label {
      font-weight: 500;
      cursor: pointer;
      user-select: none;
    }

    .required-marker {
      color: var(--error-color);
      margin-left: 0.125rem;
    }

    .helper-text {
      font-size: 0.875rem;
      color: var(--text-muted);
      margin: 0.25rem 0 0 2rem;
    }

    .error-text {
      font-size: 0.875rem;
      color: var(--error-color);
      margin: 0.5rem 0 0 2rem;
      font-weight: 500;
    }

    button {
      width: 100%;
      padding: 0.75rem 1rem;
      background-color: var(--primary-color);
      color: white;
      border: none;
      border-radius: var(--radius);
      font-size: 1rem;
      font-weight: 600;
      cursor: pointer;
      transition: background-color 0.2s;
    }

    button:hover {
      background-color: var(--primary-hover);
    }

    button:focus-visible {
      outline: 2px solid var(--primary-color);
      outline-offset: 2px;
    }

    .success-message {
      text-align: center;
      padding: 1rem;
    }

    .success-icon {
      color: #059669;
      font-size: 3rem;
      margin-bottom: 1rem;
    }
  </style>
</head>
<body>
  <div id="root"></div>

  <!-- Load React and Babel -->
  <script src="https://unpkg.com/react@18/umd/react.production.min.js" crossorigin></script>
  <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js" crossorigin></script>
  <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>

  <script type="text/babel">
    const { useState, useRef } = React;

    function ConsentForm() {
      const [isAgreed, setIsAgreed] = useState(false);
      const [error, setError] = useState(null);
      const [isSubmitted, setIsSubmitted] = useState(false);
      const checkboxRef = useRef(null);

      const handleSubmit = (e) => {
        e.preventDefault();

        if (!isAgreed) {
          setError("Error: You must agree to the terms of use to continue.");
          checkboxRef.current?.focus();
          return;
        }

        setError(null);
        setIsSubmitted(true);
      };

      if (isSubmitted) {
        return (
          <div className="success-message" role="status">
            <div className="success-icon" aria-hidden="true">✓</div>
            <h1>Thank you!</h1>
            <p>Your agreement has been successfully recorded.</p>
          </div>
        );
      }

      return (
        <div className="card">
          <header>
            <h1>Terms of Use</h1>
            <p className="intro">Please review and accept our terms to proceed with your registration.</p>
          </header>
          <form onSubmit={handleSubmit} noValidate>
            <div className="form-field">
              <div className="checkbox-container">
                <input
                  type="checkbox"
                  id="consent-checkbox"
                  ref={checkboxRef}
                  checked={isAgreed}
                  onChange={(e) => {
                    setIsAgreed(e.target.checked);
                    if (e.target.checked) setError(null);
                  }}
                  required
                  aria-describedby={error ? "consent-helper consent-error" : "consent-helper"}
                  aria-invalid={error ? "true" : "false"}
                />
                <label htmlFor="consent-checkbox">
                  I agree to the Terms of Use
                  <span className="required-marker" aria-hidden="true">*</span>
                  <span className="sr-only">(Required)</span>
                </label>
              </div>
              <p id="consent-helper" className="helper-text">
                Checking this box confirms you have read our policy.
              </p>
              {error && (
                <p id="consent-error" className="error-text">
                  {error}
                </p>
              )}
            </div>
            <button type="submit">
              Accept and Continue
            </button>
          </form>
        </div>
      );
    }

    function App() {
      return (
        <main>
          <ConsentForm />
        </main>
      );
    }

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<App />);
  </script>
</body>
</html>
